    [oldNo, newNo, remOld, remNew] = [hunk.oldStart, hunk.newStart, hunk.oldLines, hunk.newLines];
    if (file.additions + file.deletions > MAX_LINES_PER_FILE) file.truncated = true;
    else file.hunks.push(hunk);
