              <span className={`dn ${lc}`}>{L?.o ?? ''}</span>
              <span className={`dc ${lc} hl-line`} style={st}>{L ? renderContent(L.s, toks.get(L), words.get(L)) : ''}</span>
              <span className={`dn ${rc}`}>
                {R && gutterBtn(R)}
