        const el = t.toolUseId ? await revealItem(t.sessionId, `tool-${t.toolUseId}`, t.toolUseId) : null;
        if (el) {
          el.scrollIntoView({ behavior: 'smooth', block: 'center' });
          el.classList.add('flash');
          setTimeout(() => el.classList.remove('flash'), 1400);
        }
      }, 400);
