  return (
    <>
      <button
        ref={ref}
        className={`touches${open ? ' on' : ''}`}
        title={`Changed in ${plural(n, 'session')}`}
        onClick={(e) => {
          e.stopPropagation();
          setOpen(!open);
        }}
      >
        <History size={11} />
        <span className="tnum">{n}</span>
      </button>
      <Popover anchor={ref.current} open={open} onClose={() => setOpen(false)} placement="bottom-end" width={360}>
        <div className="touches-pop">
