interface Entry {
  name: string;
  path: string;
  type: 'dir' | 'file';
  size: number;
  heavy?: boolean;
}

interface Tab {
  path: string;
  doc: string;
  saved: string;
  mtime?: number;
  binary?: boolean;
  dataUrl?: string;
  tooLarge?: boolean;
  size?: number;
  error?: string;
