                      <Row key={s.id} s={s} active={s.id === activeId} unread={unread[s.id]} now={now} q={q} />
                    ))}
                    {g.items.length > limit && (
                      <button className="side-more" onClick={() => setShowAll({ ...showAll, [g.key]: true })}>
                        Show {g.items.length - limit} more
