}
.inbox-rail-h {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: var(--fs-h);
  font-weight: 600;
  letter-spacing: -0.01em;
  color: var(--text);
  padding: 4px 0 2px;
}
.sched {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 6px;
  padding: 10px 8px 12px 12px;
  border-radius: 12px;
  background: var(--card);
  box-shadow: var(--card-shadow);
  overflow: hidden;
  transition: box-shadow var(--t-fast);
  animation: rise var(--t-panel) var(--ease) both;
}
.sched:hover {
  box-shadow: var(--card-shadow-hover);
}
.sched.on {
  box-shadow: 0 0 0 1.5px var(--accent-line);
}
.sched.off .sched-name,
