  color: var(--text-3);
}
.sched-main {
  display: grid;
  gap: 2px;
  min-width: 0;
  text-align: left;
}
.sched-name {
  font-size: var(--fs-small);
  font-weight: 560;
}
.sched-sub {
  font-size: var(--fs-micro);
