}
.sched-next.err {
  color: var(--err);
}
.sched-end {
  display: flex;
  align-items: center;
  gap: 2px;
}
.sched-end .switch {
  margin-right: 4px;
}
.sched-check {
  display: none;
}
/* the wait until the next run, as a bar along the bottom edge; a running one sweeps */
.sched-bar {
  position: absolute;
  left: 12px;
  right: 12px;
  bottom: 0;
  height: 2px;
  border-radius: 1px;
  background: var(--fill-2);
  overflow: hidden;
}
.sched-bar > span {
  display: block;
  height: 100%;
  border-radius: 1px;
  background: var(--text-3);
  transition: width var(--spring-soft-t) var(--spring-soft);
}
.sched.running .sched-bar > span {
  background: var(--accent);
  animation: sched-sweep 1.4s var(--ease-io) infinite;
}
@keyframes sched-sweep {
  from {
    transform: translateX(-100%);
  }
  to {
    transform: translateX(250%);
  }
}
.sched.off .sched-bar {
  opacity: 0.4;
}

/* schedule dialog */
.sd {
  display: grid;
  gap: 16px;
}
.sd-folder {
  width: 100%;
  height: 36px;
  cursor: pointer;
}
.sd-when {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.sd-when .select-btn {
  width: auto;
  min-width: 170px;
}
.sd-inline {
  display: inline-flex;
