}
.sd-preview {
  max-width: 55%;
}

/* ================================================================ file touches (which sessions changed a file) */
.touches {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  flex: none;
  height: 18px;
  padding: 0 5px;
  border-radius: 999px;
